<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { api } from '../../shared/api/client'
import type { Choices, Company, Job, Page, Source, User } from '../../shared/api/types'
import { errorText, notify, time } from '../../shared/display'
import Icon from '../../shared/Icon.vue'
const tab = ref('sources'), loading = ref(false), error = ref(''), busy = ref(false)
const sources = ref<Source[]>([]), companies = ref<Company[]>([]), jobs = ref<Page<Job>>({ items: [], total: 0, limit: 20, offset: 0 }), users = ref<User[]>([]), choices = ref<Choices>({ dictionary: [], cities: [], companies: [] })
const company = ref<Company | null>(null), companyDialog = ref<HTMLDialogElement | null>(null), accountDialog = ref<HTMLDialogElement | null>(null), account = ref<User | null>(null), accountError = ref('')
const companyForm = reactive({ industry: '', nature: '', tiers: [] as string[], basis: '' })
const accountForm = reactive({ username: '', password: '', role: 'standard', vip_expires_at: '' })
const options = (kind: string) => choices.value.dictionary.filter(item => item.kind === kind)
const sourceLabels: Record<string, string> = { pending: '尚未采集', running: '正在核验', succeeded: '最近核验成功', failed: '最近核验失败', restricted: '访问受限' }
const roleLabels: Record<string, string> = { standard: '普通用户', vip: 'VIP', admin: '管理员' }
async function load() {
  loading.value = true; error.value = ''
  try { const [s, c, j, u, f] = await Promise.all([api<{items: Source[]}>('/admin/sources'), api<{items: Company[]}>('/admin/companies'), api<Page<Job>>('/admin/jobs?status=all&limit=20&offset=' + jobs.value.offset), api<{items: User[]}>('/admin/users?limit=100'), api<Choices>('/jobs/filters')]); sources.value = s.items; companies.value = c.items; jobs.value = j; users.value = u.items; choices.value = f }
  catch (value) { error.value = errorText(value) } finally { loading.value = false }
}
async function toggleSource(source: Source) { busy.value = true; try { await api('/admin/sources/' + source.code, { method: 'PATCH', body: { enabled: !source.enabled } }); await load(); notify(source.enabled ? '已暂停此来源的后续采集与发布' : '已启用此来源') } catch (value) { notify(errorText(value), 'error') } finally { busy.value = false } }
function editCompany(value: Company) { company.value = value; Object.assign(companyForm, { industry: value.industry, nature: value.nature, tiers: [...value.tiers], basis: value.basis }); companyDialog.value?.showModal() }
async function saveCompany() { if (!company.value) return; busy.value = true; try { await api('/admin/companies/' + company.value.code, { method: 'PATCH', body: companyForm }); companyDialog.value?.close(); await load(); notify('公司标签与依据已保存') } catch (value) { notify(errorText(value), 'error') } finally { busy.value = false } }
async function publish(job: Job) { const note = window.prompt(job.published ? '填写隐藏原因。个人投递记录会保留。' : '填写重新发布的核验依据。', job.review_note || ''); if (!note?.trim()) return; busy.value = true; try { await api('/admin/jobs/' + job.id, { method: 'PATCH', body: { published: !job.published, note } }); await load(); notify(job.published ? '已隐藏公共岗位' : '已重新发布岗位') } catch (value) { notify(errorText(value), 'error') } finally { busy.value = false } }
function localDateTime(value?: string | null) { if (!value) return ''; const date = new Date(value); return new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 16) }
function openAccount(value: User | null) { account.value = value; accountError.value = ''; Object.assign(accountForm, { username: value?.username ?? '', password: '', role: value?.role ?? 'standard', vip_expires_at: localDateTime(value?.vip_expires_at) }); accountDialog.value?.showModal() }
async function saveAccount() {
  busy.value = true; accountError.value = ''
  try { const role = { role: accountForm.role, vip_expires_at: accountForm.role === 'vip' && accountForm.vip_expires_at ? new Date(accountForm.vip_expires_at).toISOString() : null }; if (account.value) await api('/admin/users/' + account.value.id + '/role', { method: 'PATCH', body: role }); else await api('/admin/users', { method: 'POST', body: { username: accountForm.username, password: accountForm.password, ...role } }); accountForm.password = ''; accountDialog.value?.close(); await load(); notify('账号权限已保存') }
  catch (value) { accountError.value = errorText(value) } finally { busy.value = false }
}
async function toggleUser(user: User) { if (!window.confirm(user.disabled ? '重新启用这个账号？原有登录状态不会恢复。' : '停用这个账号？其所有设备会立即退出。')) return; busy.value = true; try { await api('/admin/users/' + user.id + '/disabled', { method: 'PATCH', body: { disabled: !user.disabled } }); await load(); notify('账号状态已更新') } catch (value) { notify(errorText(value), 'error') } finally { busy.value = false } }
async function jobPage(delta: number) { jobs.value.offset = Math.max(0, jobs.value.offset + delta * 20); await load() }
const enabledCount = computed(() => sources.value.filter(item => item.enabled).length)
void load()
</script>
<template>
  <section class="page-heading"><div><span class="eyebrow">管理中心</span><h1>让数据与权限，保持清晰。</h1><p>维护来源、标签、公开岗位与账号。管理修改会保留审计记录。</p></div><span class="heading-decoration"><Icon name="shield" /></span></section>
  <div class="type-tabs admin-tabs"><button v-for="[key, label] in [['sources', '招聘来源'], ['companies', '公司标签'], ['jobs', '岗位维护'], ['users', '账号与权限']]" :key="key" :class="{ active: tab === key }" @click="tab = key">{{ label }}</button></div>
  <div v-if="error" class="empty-state" role="alert"><h2>暂时无法加载管理数据</h2><p>{{ error }}</p><button class="button secondary" @click="load">重新加载</button></div>
  <div v-else-if="loading" class="loading-state"><span class="spinner"></span>正在读取管理数据…</div>
  <section v-else-if="tab === 'sources'" class="admin-source-list"><div class="admin-section-heading"><span>{{ sources.length }} 个来源 · {{ enabledCount }} 个启用</span><button class="button ghost compact" @click="load">刷新状态</button></div><article v-for="source in sources" :key="source.code" class="panel source-card"><div class="source-icon"><Icon name="shield" /></div><div><h2>{{ source.name }}</h2><p>{{ source.coverage }}</p><div class="tag-row"><span class="tag" :class="{ warning: ['failed', 'restricted'].includes(source.last_status) }">{{ sourceLabels[source.last_status] ?? '待核实' }}</span><span class="tag subtle">{{ source.job_count }} 个已发布岗位广告</span></div><small>最近成功 {{ time(source.last_succeeded_at) }} · 最近尝试 {{ time(source.last_checked_at) }}</small><p v-if="source.last_status === 'failed' || source.last_status === 'restricted'" class="source-failure">来源核验未完成，旧岗位会保留。请结合岗位核验时间确认。</p><a class="text-link" :href="source.official_url" target="_blank" rel="noopener noreferrer">查看官方入口<Icon name="external" /></a></div><button class="button secondary compact" :disabled="busy" @click="toggleSource(source)">{{ source.enabled ? '暂停来源' : '启用来源' }}</button></article><p class="field-hint">启用来源允许后续采集，不代表已完成更新。这里显示实际运行结果。</p></section>
  <section v-else-if="tab === 'companies'" class="panel admin-table-panel"><div class="admin-section-heading"><h2>公司分类与依据</h2><span class="muted">性质与规模未核实时保持未知</span></div><article v-for="item in companies" :key="item.code" class="company-admin-row"><div><h3>{{ item.name }}</h3><div class="tag-row"><span class="tag">{{ options('industry').find(x => x.code === item.industry)?.name }}</span><span class="tag subtle">{{ options('nature').find(x => x.code === item.nature)?.name }}</span><span v-for="tier in item.tiers" :key="tier" class="tag warm">{{ options('tier').find(x => x.code === tier)?.name }}</span></div><p class="muted">{{ item.basis }}</p></div><button class="button secondary compact" @click="editCompany(item)">编辑标签</button></article></section>
  <section v-else-if="tab === 'jobs'" class="panel admin-table-panel"><div class="admin-section-heading"><h2>公共岗位 · {{ jobs.total }} 个广告</h2><span class="muted">包含已隐藏及已关闭岗位</span></div><div v-if="!jobs.items.length" class="empty-state"><h2>还没有正式岗位</h2><p>来源完整核验成功后，实际岗位会在这里出现。</p></div><article v-for="job in jobs.items" :key="job.id" class="company-admin-row"><div><small>{{ job.company_name }} · {{ job.campaign_name }}</small><h3>{{ job.title }}</h3><span class="tag" :class="{ warning: !job.published }">{{ job.published ? '已发布' : '已隐藏' }}</span><p v-if="job.review_note" class="muted">{{ job.review_note }}</p></div><button class="button secondary compact" :disabled="busy" @click="publish(job)">{{ job.published ? '隐藏岗位' : '重新发布' }}</button></article><div class="pagination"><span>第 {{ Math.floor(jobs.offset / 20) + 1 }} 页</span><div><button class="button ghost compact" :disabled="!jobs.offset" @click="jobPage(-1)">上一页</button><button class="button ghost compact" :disabled="jobs.offset + 20 >= jobs.total" @click="jobPage(1)">下一页</button></div></div></section>
  <section v-else class="panel admin-table-panel"><div class="admin-section-heading"><h2>账号与权限</h2><button class="button primary compact" @click="openAccount(null)"><Icon name="plus" />创建账号</button></div><article v-for="user in users" :key="user.id" class="company-admin-row"><div><h3>{{ user.username }}</h3><div class="tag-row"><span class="tag">{{ roleLabels[user.role] }}</span><span v-if="user.disabled" class="tag warning">已停用</span></div><p v-if="user.role === 'vip'" class="muted">{{ user.vip_expires_at ? '有效期至 ' + time(user.vip_expires_at) : '长期有效' }}</p></div><div class="button-row"><button class="button secondary compact" @click="openAccount(user)">修改权限</button><button class="button ghost compact" :disabled="busy" @click="toggleUser(user)">{{ user.disabled ? '启用' : '停用' }}</button></div></article><p class="field-hint">本页显示最近 100 个账号。VIP 到期与权限撤销以服务端当前状态为准。</p></section>
  <dialog ref="companyDialog" class="edit-dialog"><form @submit.prevent="saveCompany"><header class="dialog-header"><h2>编辑 {{ company?.name }} 标签</h2><button type="button" class="icon-button" aria-label="关闭公司编辑" @click="companyDialog?.close()"><Icon name="close" /></button></header><div class="dialog-content"><div class="form-row"><label>行业<select v-model="companyForm.industry"><option v-for="item in options('industry')" :key="item.code" :value="item.code">{{ item.name }}</option></select></label><label>企业性质<select v-model="companyForm.nature"><option v-for="item in options('nature')" :key="item.code" :value="item.code">{{ item.name }}</option></select></label></div><fieldset><legend>企业规模标签</legend><label v-for="item in options('tier')" :key="item.code" class="checkbox-label"><input v-model="companyForm.tiers" type="checkbox" :value="item.code" />{{ item.name }}</label></fieldset><label>标注依据<textarea v-model="companyForm.basis" rows="3" maxlength="1000" required placeholder="填写可核实依据；主观规模标签应注明管理员分类" /></label></div><footer class="dialog-footer"><span></span><button class="button primary" :disabled="busy">保存标签</button></footer></form></dialog>
  <dialog ref="accountDialog" class="edit-dialog"><form @submit.prevent="saveAccount"><header class="dialog-header"><h2>{{ account ? '修改 ' + account.username + ' 的权限' : '创建账号' }}</h2><button type="button" class="icon-button" aria-label="关闭账号编辑" @click="accountDialog?.close()"><Icon name="close" /></button></header><div class="dialog-content"><template v-if="!account"><label>账号<input v-model="accountForm.username" required minlength="3" maxlength="40" pattern="[a-zA-Z0-9][a-zA-Z0-9._-]{2,39}" autocomplete="off" /></label><label>初始密码<input v-model="accountForm.password" required type="password" minlength="12" maxlength="72" autocomplete="new-password" /><small>12–72 字节，请通过私密渠道交付。</small></label></template><label>账号角色<select v-model="accountForm.role"><option value="standard">普通用户</option><option value="vip">VIP</option><option value="admin">管理员</option></select></label><label v-if="accountForm.role === 'vip'">VIP 到期时间<input v-model="accountForm.vip_expires_at" type="datetime-local" /><small>留空表示长期有效。</small></label><p v-if="accountError" class="inline-error" role="alert">{{ accountError }}</p></div><footer class="dialog-footer"><span></span><button class="button primary" :disabled="busy">{{ busy ? '保存中…' : '保存账号' }}</button></footer></form></dialog>
</template>
